const glass=document.querySelector('.glass');for(let i=0;i<42;i++){let strip=document.createElement('i');glass.appendChild(strip)}const strips=[...glass.children];document.querySelector('.hero').addEventListener('pointermove',e=>{const rect=e.currentTarget.getBoundingClientRect(),index=Math.floor((e.clientX-rect.left)/rect.width*strips.length);strips.forEach((s,i)=>s.classList.toggle('active',Math.abs(index-i)<3))});document.querySelector('.hero').addEventListener('pointerleave',()=>strips.forEach(s=>s.classList.remove('active')));const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));const menu=document.querySelector('.menu'),nav=document.querySelector('.header nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close menu':'Open menu');menu.textContent=open?'×':'☰'});nav.addEventListener('click',e=>{if(e.target.tagName==='A'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');menu.textContent='☰'}});
